import { cx, initials } from "../../lib/format.js";
import { Photo } from "../media/Photo.jsx";
import { AppLink } from "../ui/AppLink.jsx";

/**
 * The monogram: initials in the display face inside a thin circle. Drawn in
 * currentColor, so it follows the theme. It stands in for the avatar when
 * there is none. (The favicon is the same drawing, generated by `npm run icons`.)
 * @param {{ name: string, size?: number, className?: string }} props
 */
export function Monogram({ name, size = 32, className }) {
  return (
    <svg viewBox="0 0 32 32" width={size} height={size} aria-hidden="true" className={className}>
      <circle cx="16" cy="16" r="15.25" fill="none" stroke="currentColor" strokeWidth="1" />
      <text
        x="16"
        y="20.75"
        textAnchor="middle"
        fontSize="13"
        fill="currentColor"
        className="font-display font-medium tracking-tight"
      >
        {initials(name)}
      </text>
    </svg>
  );
}

/**
 * The logo: the round avatar from site.json (or the monogram) plus wordmark,
 * linking home. The visible name is the link's accessible name (WCAG "label
 * in name"); only the variant without a wordmark needs an aria-label.
 * @param {object} props
 * @param {string} props.name
 * @param {import("../../lib/photo-url.js").PhotoRecord | null} [props.avatar]
 * @param {boolean} [props.wordmark]  Show the name beside the mark
 * @param {string} [props.className]
 * @param {() => void} [props.onClick]
 */
export function Brand({ name, avatar, wordmark = true, className, onClick }) {
  return (
    <AppLink
      to="/"
      aria-label={wordmark ? undefined : `${name}, home`}
      onClick={onClick}
      className={cx("flex min-h-11 shrink-0 items-center gap-2.5", className)}
    >
      {avatar ? (
        <Photo
          photo={avatar}
          alt=""
          sizes="32px"
          eager
          className="aspect-square! size-8 rounded-pill object-cover"
        />
      ) : (
        <Monogram name={name} />
      )}
      {wordmark && <span className="text-body-s font-medium whitespace-nowrap">{name}</span>}
    </AppLink>
  );
}
